code='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Connected foreground components identify the separate pattern bands.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]!=bg:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append(cells)
    for cells in comps:
        rows=sorted(set(r for r,c in cells))
        # Find short repeated horizontal motifs at the right edge of each row.
        motifs={}
        for r in rows:
            fg=[c for c,v in enumerate(grid[r]) if v!=bg]
            if not fg: continue
            last=fg[-1]
            # Include one background cell after the last mark when it completes a tile.
            ends=[last]
            if last+1<w and grid[r][last+1]==bg: ends.append(last+1)
            best=None
            for end in ends:
                for p in range(2,5):
                    start=end-2*p+1
                    if start<0: continue
                    seq=grid[r][start:end+1]
                    if all(seq[i]==seq[i%p] for i in range(len(seq))) and any(v!=bg for v in seq):
                        # Prefer the shortest tile that explains the suffix.
                        if best is None or p<best[0]: best=(p,start,end,seq[:p])
            # A repeated motif at the beginning can anchor a continuation when the
            # foreground run later becomes solid.
            if best is None:
                for p in range(2,5):
                    if w>=2*p and all(grid[r][i]==grid[r][i%p] for i in range(2*p)) and any(v!=bg for v in grid[r][:p]):
                        best=(p,0,fg[-1],grid[r][:p]); break
            if best: motifs[r]=best
        # Determine the row(s) that carry a plain horizontal bar.
        runs={}
        for r in rows:
            best_run=(0,0,-1)
            c=0
            while c<w:
                if grid[r][c]==bg: c+=1; continue
                a=c
                while c+1<w and grid[r][c+1]==grid[r][c]: c+=1
                if c-a+1>best_run[0]: best_run=(c-a+1,a,c)
                c+=1
            runs[r]=best_run
        has_motif=bool(motifs)
        if has_motif:
            # Extend periodic rows and long solid rows in the same motif.
            for r,(p,start,end,tile) in motifs.items():
                anchor=end
                for c in range(anchor+1,w):
                    v=tile[(c-start)%p]
                    if v!=bg and out[r][c]==bg: out[r][c]=1
            # A solid row alongside a periodic row continues with its local color.
            for r,(n,a,b) in runs.items():
                if n>=6 and r not in motifs:
                    # Use the row's own solid phase, except when a 2-period tile
                    # is established elsewhere in this component.
                    p2=[m for m in motifs.values() if m[0]==2]
                    if p2 and n>=7:
                        # Align the repeated foreground/background cadence to the
                        # first established 2-cell motif.
                        _,s,e,tile=p2[0]
                        for c in range(b+1,w):
                            v=tile[(c-s)%2]
                            if v!=bg and out[r][c]==bg: out[r][c]=1
                    else:
                        for c in range(b+1,w):
                            if out[r][c]==bg: out[r][c]=1
        else:
            # For a simple multi-row shape, continue only its longest horizontal
            # bar. A standalone bar is itself the repeated unit.
            chosen=max(rows,key=lambda r:runs[r][0])
            n,a,b=runs[chosen]
            if n>=3:
                for c in range(b+1,w):
                    if out[chosen][c]==bg: out[chosen][c]=1
    return out
